    // Local WPF adaptation of existing SVG paths; no runtime network or font dependency.
    // QQ: ByteDance IconPark tencent-qq (Apache-2.0), paths unchanged, brand palette applied.
    // https://api.iconify.design/icon-park/tencent-qq.svg
    // WeChat: Simple Icons 15.22.0 (CC0-1.0); Feishu: callback-io/allogo (MIT).
    // WeCom: Tencent/tdesign-icons logo-wecom (MIT); DingTalk: Richard9394/MingCute (Apache-2.0).
    // The four latter SVGs were transcribed from Apache Maka bot-brand-logo.tsx (Apache-2.0):
    // https://github.com/apache/maka/blob/main/packages/ui/src/bot-brand-logo.tsx
    // Changes: SVG converted to frozen WPF drawings; original paths and aspect ratios preserved.
    // Full sources, copyright, licenses and trademark boundary: assets/im-logos.LICENSE.txt.
    internal static class ImChannelLogos
    {
        static readonly Dictionary<string, ImageSource> images = new Dictionary<string, ImageSource>();

        internal static FrameworkElement Image(string kind, double size = 24)
        {
            kind = (kind ?? String.Empty).Trim().ToLowerInvariant();
            if (kind == "weixin") kind = "wechat";
            if (kind == "lark") kind = "feishu";
            if (kind == "wxwork") kind = "wecom";
            ImageSource source;
            if (!images.TryGetValue(kind, out source))
            {
                switch (kind)
                {
                    case "qq": source = QQ(); break;
                    case "wechat": source = WeChat(); break;
                    case "feishu": source = Feishu(); break;
                    case "dingtalk": source = DingTalk(); break;
                    case "wecom": source = WeCom(); break;
                    default: throw new ArgumentException("Unknown IM channel: " + kind, "kind");
                }
                images[kind] = source;
            }
            return new System.Windows.Controls.Image
            {
                Name = "ImChannelLogo_" + kind,
                Source = source,
                Width = size,
                Height = size,
                Stretch = Stretch.Uniform,
                VerticalAlignment = VerticalAlignment.Center,
                HorizontalAlignment = HorizontalAlignment.Center,
                IsHitTestVisible = false
            };
        }

        static DrawingGroup Tile(string fill)
        {
            var group = new DrawingGroup();
            group.Children.Add(new GeometryDrawing(Brush(fill), null, new RectangleGeometry(new Rect(0, 0, 24, 24), 5, 5)));
            return group;
        }
        static Brush Brush(string color)
        {
            var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));
            brush.Freeze();
            return brush;
        }
        static void Add(DrawingGroup group, string data, string fill, bool evenOdd)
        {
            var geometry = Geometry.Parse((evenOdd ? "F0 " : "F1 ") + data);
            geometry.Freeze();
            group.Children.Add(new GeometryDrawing(Brush(fill), null, geometry));
        }
        static ImageSource Finish(DrawingGroup group)
        {
            group.Freeze();
            var image = new DrawingImage(group);
            image.Freeze();
            return image;
        }
